  {
    .move_mms2 = 3000,
    .quiet_mms2 = 500,
    .gravity_min_mms2 = 8000,
    .gravity_max_mms2 = 12000,
    .tilt_enter_cos = 800,
    .tilt_leave_cos = 950,
    .settle_us = 400000,
    .cooldown_us = 2000000,
    .max_gap_us = 250000
  };
