/****************************************************************************
 * apps/bk7258/native-apps/shake_decide.c
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 ****************************************************************************/

/* "Shake to decide": waits with a thinking face for up to the run seconds.
 * The first movement reported by the product motion classifier shows a
 * happy (yes) or neutral (no) answer for three seconds with one haptic pulse
 * request, then completes with result 1 or 2.  No movement completes with
 * result 0.  The pulse is a request; the product gates decide if it is felt.
 *
 * Manifest: abi 3, permissions display,motion,haptic,
 * results ["去吧", "再想想"].
 */

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include "bk7258_native_abi.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define DECIDE_ANSWER_MS 3000u
#define DECIDE_IDLE_MS 2000u
#define DECIDE_HAPPY 1u
#define DECIDE_THINKING 2u
#define DECIDE_NEUTRAL 3u
#define DECIDE_YES 1u
#define DECIDE_NO 2u

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct decide_s
{
  uint32_t duration;
  uint32_t answer_until;
  uint32_t idle_shown;
  uint32_t answer;
};

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static int decide_start(void *memory, uint32_t argument)
{
  struct decide_s *state = memory;
  state->duration = argument * 1000u;
  state->answer_until = 0;
  state->idle_shown = UINT32_MAX;
  state->answer = 0;
  return 0;
}

static int decide_step(void *memory, uint32_t elapsed,
                       const struct bknative_input3_s *input,
                       struct bknative_output3_s *output)
{
  struct decide_s *state = memory;

  if (state->answer)
    {
      /* Keep the answer on screen for its full time, then report it. */

      if (elapsed >= state->answer_until)
        {
          output->result = state->answer;
          return 1;
        }

      return 0;
    }

  if (elapsed >= state->duration)
    {
      return 1;
    }

  output->base.frame.progress = elapsed / (state->duration / 100u + 1u);
  if (input->base.events & BKNATIVE_EVENT_MOVED)
    {
      state->answer = (input->base.random & 1u) ? DECIDE_YES : DECIDE_NO;
      output->base.frame.expression = state->answer == DECIDE_YES ?
                                      DECIDE_HAPPY : DECIDE_NEUTRAL;
      output->base.frame.duration_ms = DECIDE_ANSWER_MS;
      output->base.haptic = 1;
      state->answer_until = elapsed + DECIDE_ANSWER_MS;
      return 0;
    }

  /* Refresh the waiting face before its display intent expires. */

  if (state->idle_shown == UINT32_MAX ||
      elapsed - state->idle_shown >= DECIDE_IDLE_MS)
    {
      output->base.frame.expression = DECIDE_THINKING;
      output->base.frame.duration_ms = DECIDE_IDLE_MS + 500u;
      state->idle_shown = elapsed;
    }

  return 0;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

const struct bknative_program_s *shaniu_native_entry(void)
{
  static const struct bknative_program_s program =
  {
    .abi = BKNATIVE_ABI_V3,
    .state_size = sizeof(struct decide_s),
    .start = decide_start,
    .step3 = decide_step,
    .saved_size = 0
  };

  return &program;
}

/****************************************************************************
 * apps/bk7258/native-apps/nudge.c
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 ****************************************************************************/

/* "Nudge": a short reminder, normally started by the schedule (for example
 * a daily drink-water time).  It shows a happy face and requests a pulse at
 * 0, 20 and 40 seconds.  Picking up or tilting the device completes it with
 * result 1; no response within the run seconds completes with result 2.
 *
 * Saved state (16 bytes) keeps today's completions and a daily streak.  The
 * streak needs trusted local time ("clock"); without it only the total
 * count advances.
 *
 * Manifest: abi 3, permissions display,motion,haptic,clock,storage,
 * results ["完成", "错过"].
 */

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include "bk7258_native_abi.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define NUDGE_PULSE_MS 20000u
#define NUDGE_PULSES 3u
#define NUDGE_FACE_MS 2500u
#define NUDGE_HAPPY 1u
#define NUDGE_THINKING 2u
#define NUDGE_DONE 1u
#define NUDGE_MISSED 2u

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct nudge_saved_s
{
  uint32_t day;           /* local day of count_today, or unknown */
  uint32_t count_today;
  uint32_t streak;        /* consecutive local days with a completion */
  uint32_t total;
};

struct nudge_s
{
  struct nudge_saved_s saved;  /* first: loaded/saved by the manager */
  uint32_t duration;
  uint32_t pulses;
  uint32_t face_shown;
};

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static int nudge_start(void *memory, uint32_t argument)
{
  struct nudge_s *state = memory;
  state->duration = argument * 1000u;
  state->pulses = 0;
  state->face_shown = UINT32_MAX;
  return 0;
}

static void nudge_record(struct nudge_saved_s *saved, uint32_t today)
{
  saved->total++;
  if (today == BKNATIVE_TIME_UNKNOWN)
    {
      return;
    }

  if (saved->day == today)
    {
      saved->count_today++;
      return;
    }

  saved->streak = saved->day != BKNATIVE_TIME_UNKNOWN &&
                  saved->day + 1u == today && saved->count_today ?
                  saved->streak + 1u : 1u;
  saved->day = today;
  saved->count_today = 1;
}

static int nudge_step(void *memory, uint32_t elapsed,
                      const struct bknative_input3_s *input,
                      struct bknative_output3_s *output)
{
  struct nudge_s *state = memory;

  if (state->pulses &&
      (input->base.events & (BKNATIVE_EVENT_MOVED | BKNATIVE_EVENT_TILTED)))
    {
      nudge_record(&state->saved, input->day);
      output->result = NUDGE_DONE;
      return 1;
    }

  if (elapsed >= state->duration)
    {
      output->result = NUDGE_MISSED;
      return 1;
    }

  output->base.frame.progress = elapsed / (state->duration / 100u + 1u);
  if (state->pulses < NUDGE_PULSES &&
      elapsed >= state->pulses * NUDGE_PULSE_MS)
    {
      state->pulses++;
      output->base.haptic = 1;
      output->base.frame.expression = NUDGE_HAPPY;
      output->base.frame.duration_ms = NUDGE_FACE_MS;
      state->face_shown = elapsed;
      return 0;
    }

  if (elapsed - state->face_shown >= NUDGE_FACE_MS - 500u)
    {
      output->base.frame.expression = NUDGE_THINKING;
      output->base.frame.duration_ms = NUDGE_FACE_MS;
      state->face_shown = elapsed;
    }

  return 0;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

const struct bknative_program_s *shaniu_native_entry(void)
{
  static const struct bknative_program_s program =
  {
    .abi = BKNATIVE_ABI_V3,
    .state_size = sizeof(struct nudge_s),
    .start = nudge_start,
    .step3 = nudge_step,
    .saved_size = sizeof(struct nudge_saved_s)
  };

  return &program;
}

/****************************************************************************
 * apps/bk7258/native-apps/sit_reminder.c
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 ****************************************************************************/

/* "Sit reminder": stays quiet while the device keeps reporting movement.
 * After the run seconds (the stillness threshold, for example 2700 for 45
 * minutes) without a moved/tilted event it shows a happy face and requests
 * a pulse every 20 seconds, up to three times.  Movement then completes
 * with result 1; no movement within 60 seconds completes with result 2.
 * If the device never stays still for the threshold within four thresholds
 * of run time, it completes with result 3.
 *
 * Like every native app it is stopped by voice, OTA or other priority
 * owners; it is not a background service.
 *
 * Manifest: abi 3, permissions display,motion,haptic,
 * results ["起来了", "还没动", "一直在活动"].
 */

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include "bk7258_native_abi.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define SIT_PULSE_MS 20000u
#define SIT_PULSES 3u
#define SIT_ANSWER_MS 60000u
#define SIT_FACE_MS 2500u
#define SIT_HAPPY 1u
#define SIT_UP 1u
#define SIT_MISSED 2u
#define SIT_ACTIVE 3u

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct sit_s
{
  uint32_t threshold;
  uint32_t last_move;
  uint32_t nudged_at;     /* UINT32_MAX until the reminder begins */
  uint32_t pulses;
};

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static int sit_start(void *memory, uint32_t argument)
{
  struct sit_s *state = memory;
  state->threshold = argument * 1000u;
  state->last_move = 0;
  state->nudged_at = UINT32_MAX;
  state->pulses = 0;
  return 0;
}

static int sit_step(void *memory, uint32_t elapsed,
                    const struct bknative_input3_s *input,
                    struct bknative_output3_s *output)
{
  struct sit_s *state = memory;
  bool moved = (input->base.events &
                (BKNATIVE_EVENT_MOVED | BKNATIVE_EVENT_TILTED)) != 0;

  if (state->nudged_at == UINT32_MAX)
    {
      if (moved)
        {
          state->last_move = elapsed;
        }

      if (elapsed - state->last_move >= state->threshold)
        {
          state->nudged_at = elapsed;
        }
      else
        {
          if (elapsed >= state->threshold * 4u)
            {
              output->result = SIT_ACTIVE;
              return 1;
            }

          return 0;
        }
    }
  else if (moved && state->pulses)
    {
      output->result = SIT_UP;
      return 1;
    }

  if (elapsed - state->nudged_at >= SIT_ANSWER_MS)
    {
      output->result = SIT_MISSED;
      return 1;
    }

  if (state->pulses < SIT_PULSES &&
      elapsed - state->nudged_at >= state->pulses * SIT_PULSE_MS)
    {
      state->pulses++;
      output->base.haptic = 1;
      output->base.frame.expression = SIT_HAPPY;
      output->base.frame.duration_ms = SIT_FACE_MS;
    }

  return 0;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

const struct bknative_program_s *shaniu_native_entry(void)
{
  static const struct bknative_program_s program =
  {
    .abi = BKNATIVE_ABI_V3,
    .state_size = sizeof(struct sit_s),
    .start = sit_start,
    .step3 = sit_step,
    .saved_size = 0
  };

  return &program;
}

